({
async block(tab,url,reason){const h=eval(load("helpers")),page=await h.ev(tab,"({url:location.href,text:document.body.innerText})");await h.save("job-search/founding-preflight/"+(url.match(/jobs/(\d+)/)?.[1]||"unknown")+"-2026-10-12.json",{listing_url:url,status:"blocked",reason,...page});const code="import json;from pathlib import Path;url="+JSON.stringify(url)+";reason="+JSON.stringify(reason)+"
for p in Path('job-search').glob('jobboards-wellfound-*queue.json'):
 d=json.loads(p.read_text());changed=False
 for x in d:
  if x['href']==url:x.update(status='blocked',blocker=reason);changed=True
 if changed:p.write_text(json.dumps(d,indent=2)+'\n')";text(await tools.exec_command({cmd:"python3 -c "+h.q(code),max_output_tokens:100}));},
async stage(tab,m){const h=eval(load("helpers"));await h.save("job-search/wttj-documents/"+m.id+".json",m);const r=await tools.exec_command({cmd:".venv/bin/python scripts/check-jobboard-duplicate.py "+h.q("job-search/wttj-documents/"+m.id+".json"),max_output_tokens:200});if(JSON.parse(r.output).duplicate)throw Error("Duplicate "+r.output);store("current",m);return tools.exec_command({cmd:".venv/bin/python scripts/prepare-vita-application.py "+h.q("job-search/wttj-documents/"+m.id+".json"),max_output_tokens:500,yield_time_ms:1000});},
async send(tab,id,message){const h=eval(load("helpers"));await tools.mcp__t3_code__preview_open({tabId:tab});await eval(load("wf")).fillMessage(tab,message);await h.save("job-search/applications/"+id+"/answers.json",{message});await h.save("job-search/applications/"+id+"/final-form-state-connected.json",await h.inspect(tab));return h.ev(tab,"(()=>{const b=[...document.querySelectorAll('button')].find(b=>b.innerText==='Send application');if(!b||b.disabled)throw Error('Submit unavailable');b.click();return true})()");}
})
